INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(7126010, 1089968, 58667, '<td valign="top">Now that''s a great photo! This is truly one of the best I have ever seen on this site. I just about never give 10s - so many of the photos on this site get voted 10 but are so generic and boring. I save my 10s for photos like this.</td>', 'Now that''s a great photo! This is truly one of the best I have ever seen on this site. I just about never give 10s - so many of the photos on this site get voted 10 but are so generic and boring. I save my 10s for photos like this.', '2013-11-06 01:42:54.000000', NULL, 1),
(7126029, 1090465, 142425, '<td valign="top">Unfortunately, the horizon is out of kilter.</td>', 'Unfortunately, the horizon is out of kilter.', '2013-11-06 03:52:31.000000', NULL, 1),
(7126067, 1090545, 163469, '<td valign="top">nice compseparation of rocks and color is perfect</td>', 'nice compseparation of rocks and color is perfect', '2013-11-06 08:24:45.000000', NULL, 1),
(7126120, 1090565, 100831, '<td valign="top">ring!</td>', 'ring!', '2013-11-06 11:31:34.000000', NULL, 1),
(7126150, 1090557, 110041, '<td valign="top">Appears underexposed and not clear to what I''m looking at. Highlights to the left are distracting. S-curve doesn''t lead you through the image as it should for a challenge such as this.</td>', 'Appears underexposed and not clear to what I''m looking at. Highlights to the left are distracting. S-curve doesn''t lead you through the image as it should for a challenge such as this.', '2013-11-06 12:41:23.000000', NULL, 1),
(7126151, 1090565, 110041, '<td valign="top">Interesting abstract but not really making use of an S-curve to any effect.</td>', 'Interesting abstract but not really making use of an S-curve to any effect.', '2013-11-06 12:42:46.000000', NULL, 1),
(7126152, 1090453, 110041, '<td valign="top">Not really seeing how an S-curve is really prominent or adding to this image. Not sure what the image is trying to convey - roses are hidden. Jar is not all in focus, concrete leaf is pretty ugly.<br/> <br/>Perhaps sticking with just the roses and trying to arrange them to incorporate an ''S'' would be better.</td>', 'Not really seeing how an S-curve is really prominent or adding to this image. Not sure what the image is trying to convey - roses are hidden. Jar is not all in focus, concrete leaf is pretty ugly. Perhaps sticking with just the roses and trying to arrange them to incorporate an ''S'' would be better.', '2013-11-06 12:46:05.000000', NULL, 1),
(7126160, 1090214, 110041, '<td valign="top">I find it hard to get the composition of this kind of photo hard. I''m never sure where the S should start.<br/> <br/>The left hand side of the photo is a little distracting as the interest is the rider and where he is heading (ultimately up to the right).<br/> <br/>Good depth of field and exposure.</td>', 'I find it hard to get the composition of this kind of photo hard. I''m never sure where the S should start. The left hand side of the photo is a little distracting as the interest is the rider and where he is heading (ultimately up to the right). Good depth of field and exposure.', '2013-11-06 12:52:40.000000', NULL, 1),
(7126161, 1090575, 110041, '<td valign="top">Lovely hues and warmth in the photo. I like the depth of field. The S is subtle (perhaps a little too much so).</td>', 'Lovely hues and warmth in the photo. I like the depth of field. The S is subtle (perhaps a little too much so).', '2013-11-06 12:54:04.000000', NULL, 1),
(7126164, 1090456, 167257, '<td valign="top">Looks like fun</td>', 'Looks like fun', '2013-11-06 12:58:12.000000', NULL, 1),
(7126165, 1090492, 167257, '<td valign="top">Clever</td>', 'Clever', '2013-11-06 13:00:31.000000', NULL, 1),
(7126167, 1090490, 110041, '<td valign="top">very creative.</td>', 'very creative.', '2013-11-06 13:10:12.000000', NULL, 1),
(7126168, 1090536, 110041, '<td valign="top">Great effect. I love the colours at the top of the S. Over exposed at the bottom. <br/> <br/>It is quite a literal interpretation of ''S-curve'' rather than really using the S-curve to give the impression of flow or motion. The smoke naturally gives a sense of movement, but I don''t think that is primarily what you''re trying to convey because of the ''S'' shape.</td>', 'Great effect. I love the colours at the top of the S. Over exposed at the bottom.  It is quite a literal interpretation of ''S-curve'' rather than really using the S-curve to give the impression of flow or motion. The smoke naturally gives a sense of movement, but I don''t think that is primarily what you''re trying to convey because of the ''S'' shape.', '2013-11-06 13:17:01.000000', NULL, 1),
(7126169, 1090381, 110041, '<td valign="top">Looks rather soft and while it''s not an unpleasant photo, there''s not a lot going on.</td>', 'Looks rather soft and while it''s not an unpleasant photo, there''s not a lot going on.', '2013-11-06 13:17:53.000000', NULL, 1),
(7126173, 1089967, 110041, '<td valign="top">I''m drawn most to the rear wheel. Not sure if that''s because of the ''S-curve'' of the cyclist''s body or not. For some reason, I just like looking at that wheel. The rest of the shot I''m pretty nonplus over.</td>', 'I''m drawn most to the rear wheel. Not sure if that''s because of the ''S-curve'' of the cyclist''s body or not. For some reason, I just like looking at that wheel. The rest of the shot I''m pretty nonplus over.', '2013-11-06 13:22:44.000000', NULL, 1),
(7126176, 1090298, 110041, '<td valign="top">Great timing but maybe a little slow on the shutter speed? The head just looks a little soft.</td>', 'Great timing but maybe a little slow on the shutter speed? The head just looks a little soft.', '2013-11-06 13:23:41.000000', NULL, 1),
(7126180, 1090535, 110041, '<td valign="top">The curve of the road isn''t really prominent enough for me. Perhaps if you could move that mountain a bit... ;^)</td>', 'The curve of the road isn''t really prominent enough for me. Perhaps if you could move that mountain a bit... ;^)', '2013-11-06 13:26:31.000000', NULL, 1),
(7126183, 1090441, 110041, '<td valign="top">Not keen on the colours a bit over saturated for me.</td>', 'Not keen on the colours a bit over saturated for me.', '2013-11-06 13:29:11.000000', NULL, 1),
